import React, { useState, useEffect } from 'react';
import useBooks from '../features/books/hooks/useBooks';
import BookCard from '../features/books/components/BookCard';

export default function Search() {
  const [query, setQuery] = useState('');
  const [debouncedValue, setDebouncedValue] = useState('');
  const params = React.useMemo(() => ({ search: debouncedValue }), [debouncedValue]);
  const { books, loading, refetch } = useBooks(params);

  useEffect(() => {
    const timer = setTimeout(() => setDebouncedValue(query), 500);
    return () => clearTimeout(timer);
  }, [query]);

  return (
    <div className="search-page">
      <h2>Advanced Search</h2>
      <input
        type="text"
        placeholder="Search by title, author, ISBN..."
        value={query}
        onChange={(e) => setQuery(e.target.value)}
        className="search-input"
      />
      <div className="book-grid">
        {loading ? <p>Loading...</p> : books.map((b) => <BookCard key={b.id} book={b} />)}
      </div>
    </div>
  );
}
